using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "TinkererAction", menuName = "Data/Battle/Battle Actions/Hevelius/Tinkerer Action")]
public class TinkererLungeAction : PurifyCounterBasedAction
{
	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return base.playerRunData.BrokenSentinelAmount + base.playerRunData.RepairedSentinelAmount;
	}
}
